   114→  /** Attempt to restore session from stored credentials */
   115→  public static restoreSession = async (): Promise<boolean> => {
   116→    try {
   117→      const credentials = MatrixStorage.getLoginCredentials();
   118→
   119→      if (!credentials) return false;
   120→
   121→      await this.initialize(credentials.baseUrl);
   122→
   123→      if (!this.instance) throw new Error("Failed to initialize client");
   124→
   125→      // Create client with stored credentials
   126→      await this.instance.restoreSession({
   127→        accessToken: credentials.accessToken,
   128→        refreshToken: credentials.refreshToken,
   129→        userId: credentials.userId,
   130→        deviceId: credentials.deviceId,
   131→        homeserverUrl: credentials.baseUrl,
   132→        oidcData: undefined,
   133→        slidingSyncVersion: SlidingSyncVersion.Native,
   134→      });
   135→
   136→      // Verify the session is valid by making a server request
   137→      try {
   138→        this.profile = await this.instance.getProfile(credentials.userId);
   139→      } catch (error) {
   140→        console.warn("Session validation failed:", error);
   141→        throw new Error("Session is invalid or expired");
   142→      }
   143→
   144→      this.syncService = await this.instance.syncService().finish();
   145→
   146→      if (!this.syncService) {
   147→        throw new Error("Failed to initialize sync service");
   148→      }
   149→
   150→      await this.syncService.start();
   151→
   152→      // Update atoms so providers can react to the initialized service
   153→      MatrixJotaiStore.set(MatrixAtoms.matrixClient, this.instance);
   154→      MatrixJotaiStore.set(MatrixAtoms.syncService, this.syncService);
   155→      MatrixJotaiStore.set(MatrixAtoms.profile, this.profile);
   156→
   157→      return true;
   158→    } catch (error) {
   159→      console.warn("Failed to restore session:", error);
   160→
   161→      // Clear both credentials and crypto store to ensure clean state
   162→      MatrixStorage.clearLoginCredentials();
   163→      await this.clearCryptoStore();
   164→
   165→      // Reset the instance so it can be recreated fresh
   166→      this.instance = null;
   167→      this.syncService = null;
   168→
   169→      // Clear atoms
   170→      MatrixJotaiStore.set(MatrixAtoms.matrixClient, null);
   171→      MatrixJotaiStore.set(MatrixAtoms.syncService, null);
   172→
   173→      return false;
   174→    }
   175→  };
