   177→  /** Call this after logging in to create a new client instance with the provided account.  */
   178→  public static setup = async (params: Session) => {
   179→    // Clear any existing crypto store to prevent device ID mismatches
   180→    await this.clearCryptoStore();
   181→
   182→    // Stop and clear existing instances
   183→    if (this.syncService) await this.syncService.stop();
   184→    this.instance = null;
   185→    this.syncService = null;
   186→
   187→    // Save credentials for future auto-login
   188→    MatrixStorage.saveLoginCredentials({
   189→      accessToken: params.accessToken,
   190→      refreshToken: params.refreshToken,
   191→      userId: params.userId,
   192→      deviceId: params.deviceId,
   193→      baseUrl: params.homeserverUrl,
   194→    });
   195→
   196→    // Create a fresh client instance and configure it with the session + sliding sync
   197→    await this.initialize(params.homeserverUrl);
   198→
   199→    if (!this.instance) throw new Error("Failed to initialize client");
   200→
   201→    // Use local variable to help TypeScript with type narrowing
   202→    const client: ClientInterface = this.instance;
   203→
   204→    await client.restoreSession({
   205→      accessToken: params.accessToken,
   206→      refreshToken: params.refreshToken,
   207→      userId: params.userId,
   208→      deviceId: params.deviceId,
   209→      homeserverUrl: params.homeserverUrl,
   210→      oidcData: undefined,
   211→      slidingSyncVersion: SlidingSyncVersion.Native,
   212→    });
   213→
   214→    // Verify the session is valid by making a server request
   215→    // Use the params.userId since client.userId() might not be populated yet
   216→    try {
   217→      this.profile = await client.getProfile(params.userId);
   218→    } catch (error) {
   219→      console.warn("Session validation failed:", error);
   220→      throw new Error("Session is invalid or expired");
   221→    }
   222→
   223→    this.syncService = await client.syncService().finish();
   224→
   225→    if (!this.syncService) throw new Error("Failed to initialize sync service");
   226→
   227→    await this.syncService.start();
   228→    await client.encryption().waitForE2eeInitializationTasks();
   229→
   230→    // Check if we need to bootstrap cross-signing or enable backups
   231→    try {
   232→      const encryption = client.encryption();
   233→      const backupExists = await encryption.backupExistsOnServer();
   234→      console.log("Backup exists on server:", backupExists);
   235→      console.log(
   236→        "Current verification state:",
   237→        encryption.verificationState(),
   238→      );
   239→
   240→      // If no backup exists and we're the only device, we might need to set one up
   241→      const isLastDevice = await encryption.isLastDevice();
   242→      console.log("Is last device:", isLastDevice);
   243→
   244→      if (!backupExists) {
   245→        console.log("Enabling backups for cross-signing...");
   246→        await encryption.enableBackups();
   247→      }
   248→
   249→      // Update atoms so providers can react to the initialized service
   250→      MatrixJotaiStore.set(MatrixAtoms.matrixClient, this.instance);
   251→      MatrixJotaiStore.set(MatrixAtoms.syncService, this.syncService);
   252→      MatrixJotaiStore.set(MatrixAtoms.profile, this.profile);
   253→    } catch (error) {
   254→      console.warn("Failed to check backup/verification status:", error);
   255→    }
   256→  };
