   328→  /** Manually refresh the room list and update the atom */
   329→  public static refreshRoomList = async () => {
   330→    if (!this.instance) return;
   331→
   332→    try {
   333→      const roomsArray = this.getRooms();
   334→
   335→      const sortedRooms = await Promise.all(
   336→        roomsArray.map(async (room) => ({
   337→          room,
   338→          timestamp: (await room.latestEvent())?.timestamp || 0,
   339→        })),
   340→      );
   341→
   342→      const filteredAndSortedRooms = sortedRooms
   343→        .filter(({ room }) => {
   344→          const membership = room.membership();
   345→
   346→          return (
   347→            membership !== Membership.Banned &&
   348→            membership !== Membership.Left &&
   349→            membership !== Membership.Knocked
   350→          );
   351→        })
   352→        .sort((a, b) => {
   353→          const aInvited = a.room.membership() === Membership.Invited ? 1 : 0;
   354→          const bInvited = b.room.membership() === Membership.Invited ? 1 : 0;
   355→          if (aInvited !== bInvited) return bInvited - aInvited;
   356→
   357→          return Number(b.timestamp) - Number(a.timestamp);
   358→        });
   359→
   360→      MatrixJotaiStore.set(
   361→        MatrixAtoms.roomList,
   362→        filteredAndSortedRooms.map(({ room }) => room),
   363→      );
   364→    } catch (error) {
   365→      console.error("Failed to refresh room list:", error);
   366→    }
   367→  };
