   611→      (userIds) => userIds,
   612→    );
   613→
   614→    // Don't show read receipts for the sender's own message
   615→    const filteredUserIds = userIds.filter((userId) => userId !== event.sender);
   616→
   617→    if (!filteredUserIds.length) {
   618→      return [];
   619→    }
   620→
   621→    try {
   622→      const profilePromises = filteredUserIds.map((userId) =>
   623→        this.instance?.getProfile(userId),
   624→      );
   625→      const profiles = await Promise.allSettled(profilePromises);
   626→      return profiles
   627→        .filter((p) => p.status === "fulfilled")
   628→        .map((p) => p.value)
   629→        .filter((p) => p !== undefined);
   630→    } catch (error) {
   631→      console.error("Failed to get read receipt users:", error);
   632→      return [];
   633→    }
