import type { DocumentPickerResponse } from "@react-native-documents/picker";
import {
  AuthData,
  AuthDataPasswordDetails,
  ClientBuilder,
  type ClientInterface,
  type CreateRoomParameters,
  type EnableRecoveryProgressListener,
  type EventTimelineItem,
  Membership,
  messageEventContentFromMarkdown,
  PowerLevel_Tags,
  RecoveryState,
  RoomPreset,
  RoomVisibility,
  type Session,
  type SessionVerificationControllerDelegate,
  type SessionVerificationControllerInterface,
  type SessionVerificationData,
  SessionVerificationData_Tags,
  type SessionVerificationRequestDetails,
  SlidingSyncVersion,
  type SyncServiceInterface,
  type UploadParameters,
  UploadSource,
  type UserProfile,
  VerificationState,
} from "@unomed/react-native-matrix-sdk";
import { deleteJotaiStorageAdapter } from "modules/storage/utils";
import RNFS from "react-native-fs";
import { MATRIX_ENDPOINTS, MatrixStorage, SygnalURL } from "../const";
import { MatrixJotaiStore } from "../const/matrx-jotai-store";
import { MatrixAtoms } from "../jotai";

type LoginWithUsernameAndPasswordData = {
  username: string;
  password: string;
  serverUrl: string;
};

/** Callback function for verification request received */
type VerificationRequestCallback = (
  details: SessionVerificationRequestDetails,
) => void;

/** Callback function for emojis received during verification */
type VerificationEmojisCallback = (
  emojis: Array<{ symbol: string; description: string }>,
) => void;

/** Callback function for verification state changes */
type VerificationStateChangeCallback = (
  state: "request" | "accepted" | "emojis" | "success" | "failed" | "cancelled",
) => void;

const dataPath = `${RNFS.DocumentDirectoryPath}/matrix/data`;
const cachePath = `${RNFS.CachesDirectoryPath}/matrix/cache`;

const APP_ID = "com.prototyp.cloak";

export class MatrixService {
  //TODO: change every method that uses MatrixService.instance to a class method
  public static instance: ClientInterface | null;
  public static syncService: SyncServiceInterface | null;
  private static verificationController: SessionVerificationControllerInterface | null =
    null;
  public static profile: UserProfile | null = null;

  // Verification callbacks
  private static onVerificationRequest: VerificationRequestCallback | null =
    null;
  private static onVerificationEmojis: VerificationEmojisCallback | null = null;
  private static onVerificationStateChange: VerificationStateChangeCallback | null =
    null;

  /** Clear the crypto store directories to fix device ID mismatches */
  private static async clearCryptoStore() {
    try {
      const dataExists = await RNFS.exists(dataPath);
      const cacheExists = await RNFS.exists(cachePath);

      if (dataExists) {
        await RNFS.unlink(dataPath);
        console.log("Cleared crypto data store");
      }

      if (cacheExists) {
        await RNFS.unlink(cachePath);
        console.log("Cleared crypto cache store");
      }
    } catch (error) {
      console.warn("Failed to clear crypto store:", error);
    }
  }

  /** Initialize client with error handling for RTC warnings */
  public static async initialize(serverUrl: string) {
    if (!this.instance) {
      this.instance = await new ClientBuilder()
        .homeserverUrl(serverUrl)
        .autoEnableBackups(true)
        .sessionPaths(dataPath, cachePath) // enables persistent stores (needed for E2EE)
        .build();
    }
  }

  // public static isLoggedIn = () => this.instance.isLoggedIn();

  /** Check if there are stored credentials available for auto-login */
  public static hasStoredCredentials = (): boolean => {
    return MatrixStorage.hasStoredCredentials();
  };

  /** Attempt to restore session from stored credentials */
  public static restoreSession = async (): Promise<boolean> => {
    try {
      const credentials = MatrixStorage.getLoginCredentials();

      if (!credentials) return false;

      await this.initialize(credentials.baseUrl);

      if (!this.instance) throw new Error("Failed to initialize client");

      // Create client with stored credentials
      await this.instance.restoreSession({
        accessToken: credentials.accessToken,
        refreshToken: credentials.refreshToken,
        userId: credentials.userId,
        deviceId: credentials.deviceId,
        homeserverUrl: credentials.baseUrl,
        oidcData: undefined,
        slidingSyncVersion: SlidingSyncVersion.Native,
      });

      // Verify the session is valid by making a server request
      try {
        this.profile = await this.instance.getProfile(credentials.userId);
      } catch (error) {
        console.warn("Session validation failed:", error);
        throw new Error("Session is invalid or expired");
      }

      this.syncService = await this.instance.syncService().finish();

      if (!this.syncService) {
        throw new Error("Failed to initialize sync service");
      }

      await this.syncService.start();

      // Update atoms so providers can react to the initialized service
      MatrixJotaiStore.set(MatrixAtoms.matrixClient, this.instance);
      MatrixJotaiStore.set(MatrixAtoms.syncService, this.syncService);
      MatrixJotaiStore.set(MatrixAtoms.profile, this.profile);

      return true;
    } catch (error) {
      console.warn("Failed to restore session:", error);

      // Clear both credentials and crypto store to ensure clean state
      MatrixStorage.clearLoginCredentials();
      await this.clearCryptoStore();

      // Reset the instance so it can be recreated fresh
      this.instance = null;
      this.syncService = null;

      // Clear atoms
      MatrixJotaiStore.set(MatrixAtoms.matrixClient, null);
      MatrixJotaiStore.set(MatrixAtoms.syncService, null);

      return false;
    }
  };

  /** Call this after logging in to create a new client instance with the provided account.  */
  public static setup = async (params: Session) => {
    // Clear any existing crypto store to prevent device ID mismatches
    await this.clearCryptoStore();

    // Stop and clear existing instances
    if (this.syncService) await this.syncService.stop();
    this.instance = null;
    this.syncService = null;

    // Save credentials for future auto-login
    MatrixStorage.saveLoginCredentials({
      accessToken: params.accessToken,
      refreshToken: params.refreshToken,
      userId: params.userId,
      deviceId: params.deviceId,
      baseUrl: params.homeserverUrl,
    });

    // Create a fresh client instance and configure it with the session + sliding sync
    await this.initialize(params.homeserverUrl);

    if (!this.instance) throw new Error("Failed to initialize client");

    // Use local variable to help TypeScript with type narrowing
    const client: ClientInterface = this.instance;

    await client.restoreSession({
      accessToken: params.accessToken,
      refreshToken: params.refreshToken,
      userId: params.userId,
      deviceId: params.deviceId,
      homeserverUrl: params.homeserverUrl,
      oidcData: undefined,
      slidingSyncVersion: SlidingSyncVersion.Native,
    });

    // Verify the session is valid by making a server request
    // Use the params.userId since client.userId() might not be populated yet
    try {
      this.profile = await client.getProfile(params.userId);
    } catch (error) {
      console.warn("Session validation failed:", error);
      throw new Error("Session is invalid or expired");
    }

    this.syncService = await client.syncService().finish();

    if (!this.syncService) throw new Error("Failed to initialize sync service");

    await this.syncService.start();
    await client.encryption().waitForE2eeInitializationTasks();

    // Check if we need to bootstrap cross-signing or enable backups
    try {
      const encryption = client.encryption();
      const backupExists = await encryption.backupExistsOnServer();
      console.log("Backup exists on server:", backupExists);
      console.log(
        "Current verification state:",
        encryption.verificationState(),
      );

      // If no backup exists and we're the only device, we might need to set one up
      const isLastDevice = await encryption.isLastDevice();
      console.log("Is last device:", isLastDevice);

      if (!backupExists) {
        console.log("Enabling backups for cross-signing...");
        await encryption.enableBackups();
      }

      // Update atoms so providers can react to the initialized service
      MatrixJotaiStore.set(MatrixAtoms.matrixClient, this.instance);
      MatrixJotaiStore.set(MatrixAtoms.syncService, this.syncService);
      MatrixJotaiStore.set(MatrixAtoms.profile, this.profile);
    } catch (error) {
      console.warn("Failed to check backup/verification status:", error);
    }
  };

  public static getUser = () => {
    if (!this.instance) return null;
    const userId = this.instance.userId();
    return userId ? this.instance.getProfile(userId) : null;
  };

  public static getUserProfile = (userId: string) => {
    if (!this.instance) throw new Error("Client not initialized");
    return this.instance.getProfile(userId);
  };

  /** Get member info for a user in a room */
  public static getUserPowerLevel = async (roomId: string) => {
    if (!this.instance) return null;
    const room = this.instance.getRoom(roomId);
    if (!room) return null;

    const member = await room.member(this.instance.userId());

    return Number(
      member.powerLevel.tag === PowerLevel_Tags.Value
        ? member.powerLevel.inner.value
        : 0,
    );
  };

  public static removeUserFromRoom = async (
    roomId: string,
    userId: string,
    reason?: string,
  ) => {
    if (!this.instance) return;
    const room = this.instance.getRoom(roomId);
    if (!room) return;
    await room.kickUser(userId, reason);
  };

  public static banUserFromRoom = async (
    roomId: string,
    userId: string,
    reason?: string,
  ) => {
    if (!this.instance) return;
    const room = this.instance.getRoom(roomId);
    if (!room) return;
    await room.banUser(userId, reason);
  };

  public static getRooms = () => {
    if (!this.instance) throw new Error("Client not initialized");
    const rooms = this.instance.rooms();
    return rooms;
  };

  public static blockUser = async (userId: string) => {
    if (!this.instance) return;
    await this.instance.ignoreUser(userId);
  };

  public static unblockUser = async (userId: string) => {
    if (!this.instance) return;
    await this.instance.unignoreUser(userId);
  };

  public static isUserBlocked = async (userId: string) => {
    if (!this.instance) return false;
    const ignoredUsers = await this.instance.ignoredUsers();
    return ignoredUsers.includes(userId);
  };

  /** Manually refresh the room list and update the atom */
  public static refreshRoomList = async () => {
    if (!this.instance) return;

    try {
      const roomsArray = this.getRooms();

      const sortedRooms = await Promise.all(
        roomsArray.map(async (room) => ({
          room,
          timestamp: (await room.latestEvent())?.timestamp || 0,
        })),
      );

      const filteredAndSortedRooms = sortedRooms
        .filter(({ room }) => {
          const membership = room.membership();

          return (
            membership !== Membership.Banned &&
            membership !== Membership.Left &&
            membership !== Membership.Knocked
          );
        })
        .sort((a, b) => {
          const aInvited = a.room.membership() === Membership.Invited ? 1 : 0;
          const bInvited = b.room.membership() === Membership.Invited ? 1 : 0;
          if (aInvited !== bInvited) return bInvited - aInvited;

          return Number(b.timestamp) - Number(a.timestamp);
        });

      MatrixJotaiStore.set(
        MatrixAtoms.roomList,
        filteredAndSortedRooms.map(({ room }) => room),
      );
    } catch (error) {
      console.error("Failed to refresh room list:", error);
    }
  };

  /** Log in with a username and password.
   * This will return the login response directly that you have to use to set up the service. */
  public static login = async ({
    username,
    password,
    serverUrl,
  }: LoginWithUsernameAndPasswordData) => {
    await this.initialize(serverUrl);
    if (!this.instance) throw new Error("Failed to initialize client");
    await this.instance.login(username, password, undefined, undefined);
    const session = this.instance.session();
    console.log(
      this.instance.encryption().verificationState(),
      "verificationState",
    );

    // After login, we need to recreate the client with sliding sync configured
    // The login call above authenticated us and gave us session data
    // Now we destroy this instance so we can rebuild with proper sliding sync
    this.instance = null;

    return session;
  };

  public static logout = async () => {
    // Clear stored credentials and crypto store
    MatrixStorage.clearLoginCredentials();
    deleteJotaiStorageAdapter();
    await this.clearCryptoStore();

    if (this.syncService) await this.syncService.stop();
    if (this.instance) await this.instance.logout();
    this.instance = null;
    this.syncService = null;
    this.profile = null;

    // Clear atoms
    MatrixJotaiStore.set(MatrixAtoms.matrixClient, null);
    MatrixJotaiStore.set(MatrixAtoms.syncService, null);
    MatrixJotaiStore.set(MatrixAtoms.profile, null);
  };

  /** Deactivate the user's account permanently
   * Warning: This is irreversible and will delete all user data */
  public static deactivateAccount = async (password: string) => {
    if (!this.instance) throw new Error("Client not initialized");

    try {
      // First request with undefined auth_data (will always fail per UIA spec)
      try {
        await this.instance.deactivateAccount(undefined, true);
      } catch {
        // Expected to fail
      }

      console.log(this.instance.userId(), "userId");
      const userId = this.instance.userId();
      if (!userId) throw new Error("User ID not found");

      const authData = new AuthData.Password({
        passwordDetails: AuthDataPasswordDetails.create({
          identifier: userId,
          password,
        }),
      });

      // Step 4: Second request with auth data
      await this.instance.deactivateAccount(authData, true);

      // After successful deactivation, clean up local data
      await this.logout();
    } catch (error) {
      console.error("Failed to deactivate account:", error);
      throw error;
    }
  };

  public static sendMessage = async (roomId: string, message: string) => {
    if (!this.instance) throw new Error("Client not initialized");
    const room = this.instance.getRoom(roomId);
    if (!room) throw new Error("Room not found");
    const timeline = await room.timeline();
    if (!timeline) throw new Error("Timeline not found");

    // Create message content from markdown (supports plain text too)
    const messageContent = messageEventContentFromMarkdown(message);

    // Send the message and return the send handle
    await timeline.send(messageContent);
  };

  /** Create a room with optional image avatar */
  /** Get or create a direct room with a user */
  public static getOrCreateDirectRoom = async (
    userId: string,
  ): Promise<string> => {
    if (!this.instance) throw new Error("Client not initialized");

    try {
      // Check if a direct room already exists with this user
      const rooms = this.instance.rooms();
      for (const room of rooms) {
        const roomInfo = await room.roomInfo();
        if (roomInfo?.isDirect) {
          const members = await room.members();
          const memberList = members.nextChunk(100000) ?? [];
          const hasUser = memberList.some((member) => member.userId === userId);
          if (hasUser) {
            return room.id();
          }
        }
      }

      // If no direct room exists, create one
      const roomOptions: CreateRoomParameters = {
        name: undefined,
        topic: undefined,
        preset: RoomPreset.PrivateChat,
        avatar: undefined,
        isEncrypted: true,
        isDirect: true,
        visibility: new RoomVisibility.Private(),
        invite: [userId],
        powerLevelContentOverride: undefined,
        joinRuleOverride: undefined,
        historyVisibilityOverride: undefined,
        canonicalAlias: undefined,
      };

      const roomId = await this.instance.createRoom(roomOptions);
      return roomId;
    } catch (error) {
      throw new Error(`Failed to get or create direct room: ${error}`);
    }
  };

  public static createRoom = async (
    roomName: string,
    type: "private" | "public",
    image: Asset | null,
    roomTopic?: string,
  ): Promise<string> => {
    try {
      const roomOptions: CreateRoomParameters = {
        name: roomName,
        topic: roomTopic,
        preset:
          type === "private" ? RoomPreset.PrivateChat : RoomPreset.PublicChat,
        avatar: undefined,
        isEncrypted: type === "private",
        isDirect: false,
        visibility:
          type === "private"
            ? new RoomVisibility.Private()
            : new RoomVisibility.Public(),
        invite: [],
        powerLevelContentOverride: undefined,
        joinRuleOverride: undefined,
        historyVisibilityOverride: undefined,
        canonicalAlias: undefined,
      };

      if (!this.instance) throw new Error("Client not initialized");

      const roomId = await this.instance.createRoom(roomOptions);

      if (image?.base64) {
        const room = this.instance.getRoom(roomId);

        const bytes = Buffer.from(image.base64, "base64");
        const type = image.type ?? "image/jpeg";

        if (!room) throw new Error("Room not found");
        await room.uploadAvatar(type, bytes.buffer, {
          height: BigInt(32),
          width: BigInt(32),
          mimetype: type,
          size: BigInt(image.fileSize ?? 0),
          thumbnailInfo: {
            height: BigInt(32),
            width: BigInt(32),
            mimetype: type,
            size: BigInt(image.fileSize ?? 0),
          },
          thumbnailSource: undefined,
          blurhash: "",
          isAnimated: false,
        });
      }

      return roomId;
    } catch (error) {
      throw new Error(`Failed to create room: ${error}`);
    }
  };

  public static invitePeopleToRoom = async (
    roomId: string,
    invitedPeople: UserProfile[],
  ) => {
    if (!this.instance) throw new Error("Client not initialized");
    const room = this.instance.getRoom(roomId);
    if (!room) throw new Error("Room not found");
    const invites = invitedPeople.map(async ({ userId }) => {
      return room.inviteUserById(userId);
    });

    await Promise.all(invites);
  };

  public static joinRoomByAddress = async (address: string) => {
    if (!this.instance) throw new Error("Client not initialized");
    const roomPreview =
      await this.instance.getRoomPreviewFromRoomAlias(address);
    const roomId = roomPreview.info().roomId;
    await this.instance.joinRoomById(roomId);
    return roomId;
  };

  public static acceptRoomInvite = async (roomId: string) => {
    if (!this.instance) throw new Error("Client not initialized");
    const room = this.instance.getRoom(roomId);
    if (!room) throw new Error("Room not found");
    await room.join();
  };

  public static declineRoomInvite = async (roomId: string) => {
    if (!this.instance) throw new Error("Client not initialized");
    const room = this.instance.getRoom(roomId);
    if (!room) throw new Error("Room not found");
    await room.leave();
    await room.forget();
    // Manually refresh the room list to update UI immediately
    await this.refreshRoomList();
  };

  public static getSeenBy = (event: EventTimelineItem) => {
    return event.readReceipts;
  };

  public static getReadReceipts = async (event: EventTimelineItem) => {
    const userIds = Array.from(event.readReceipts.keys()).map(
      (userIds) => userIds,
    );

    // Don't show read receipts for the sender's own message
    const filteredUserIds = userIds.filter((userId) => userId !== event.sender);

    if (!filteredUserIds.length) {
      return [];
    }

    try {
      const profilePromises = filteredUserIds.map((userId) =>
        this.instance?.getProfile(userId),
      );
      const profiles = await Promise.allSettled(profilePromises);
      return profiles
        .filter((p) => p.status === "fulfilled")
        .map((p) => p.value)
        .filter((p) => p !== undefined);
    } catch (error) {
      console.error("Failed to get read receipt users:", error);
      return [];
    }
  };

  public static setNewRecoveryKey = async () => {
    if (!this.instance) throw new Error("Client not initialized");
    return this.instance.encryption().resetRecoveryKey();
  };

  public static isUser = (event: EventTimelineItem) => event.isOwn;

  public static getSenderDetails = (event: EventTimelineItem) => {
    if (!this.instance) return null;
    const senderId = event.sender;
    const sender = senderId ? this.instance.getProfile(senderId) : null;
    return sender;
  };

  public static sendAttachment = async (
    roomId: string,
    attachment: DocumentPickerResponse,
  ) => {
    if (!this.instance) throw new Error("Client not initialized");
    const room = this.instance.getRoom(roomId);
    if (!room) throw new Error("Room not found");
    const timeline = await room.timeline();
    if (!timeline) throw new Error("Timeline not found");
    timeline.sendFile(
      {
        source: new UploadSource.File({
          filename: attachment.uri.replace("file://", ""),
        }),
        caption: undefined,
        formattedCaption: undefined,
        mentions: undefined,
        inReplyTo: undefined,
      },
      {
        size: BigInt(attachment.size || 0),
        mimetype: attachment.type || "application/octet-stream",
        thumbnailInfo: undefined,
        thumbnailSource: undefined,
      },
    );
  };

  public static sendMedia = async (
    roomId: string,
    asset: Asset,
    caption?: string,
  ) => {
    if (!asset?.uri) throw new Error("No uri found");
    if (!this.instance) throw new Error("Client not initialized");
    const room = this.instance.getRoom(roomId);
    if (!room) throw new Error("Room not found");
    const timeline = await room.timeline();
    if (!timeline) throw new Error("Timeline not found");

    const type = asset.type ?? "image/jpeg";
    const assetWidth = asset.width ?? 0;
    const assetHeight = asset.height ?? 0;
    const isVideo = type.startsWith("video/");

    const fileSource: UploadParameters = {
      source: new UploadSource.File({
        filename: asset.uri.replace("file://", ""),
      }),
      caption: caption || undefined,
      formattedCaption: undefined,
      mentions: undefined,
      inReplyTo: undefined,
    };

    if (isVideo) {
      // Send as video
      const videoHandle = timeline.sendVideo(
        fileSource,
        new UploadSource.File({
          filename: asset.uri.replace("file://", ""),
        }),
        {
          height: BigInt(assetHeight),
          width: BigInt(assetWidth),
          mimetype: type,
          size: BigInt(asset.fileSize ?? 0),
          duration: asset.duration ? Math.round(asset.duration * 1000) : 0,
          thumbnailInfo: {
            height: BigInt(assetHeight),
            width: BigInt(assetWidth),
            mimetype: type,
            size: BigInt(asset.fileSize ?? 0),
          },
          thumbnailSource: undefined,
          blurhash: "",
        },
      );

      await videoHandle.join();
    } else {
      // Send as image
      const imageHandle = timeline.sendImage(
        fileSource,
        new UploadSource.File({
          filename: asset.uri.replace("file://", ""),
        }),
        {
          height: BigInt(assetHeight),
          width: BigInt(assetWidth),
          mimetype: type,
          size: BigInt(asset.fileSize ?? 0),
          thumbnailInfo: {
            height: BigInt(assetHeight),
            width: BigInt(assetWidth),
            mimetype: type,
            size: BigInt(asset.fileSize ?? 0),
          },
          thumbnailSource: undefined,
          blurhash: "",
          isAnimated: false,
        },
      );

      await imageHandle.join();
    }
  };

  public static sendEvent = async (
    roomId: string,
    eventType: string,
    content: string,
  ) => {
    if (!this.instance) throw new Error("Client not initialized");
    const room = this.instance.getRoom(roomId);
    if (!room) throw new Error("Room not found");
    await room.sendRaw(eventType, content);
  };

  public static updateProfile = async (
    displayName?: string,
    avatar?: Asset | null,
  ) => {
    if (!this.instance) throw new Error("Client not initialized");

    try {
      if (displayName) await this.instance.setDisplayName(displayName);

      if (avatar === null) {
        await this.instance.removeAvatar();
      } else if (avatar?.base64) {
        const bytes = Buffer.from(avatar.base64, "base64");
        const mimeType = avatar.type ?? "image/jpeg";

        await this.instance.uploadAvatar(mimeType, bytes.buffer);
      }

      // Refresh profile to get updated data
      const userId = this.instance.userId();
      this.profile = await this.instance.getProfile(userId);

      // Update the Jotai atom to trigger re-renders
      MatrixJotaiStore.set(MatrixAtoms.profile, this.profile);

      return this.profile;
    } catch (error) {
      console.error("Failed to update profile:", error);
      throw error;
    }
  };

  public static updateRoom = async (
    roomId: string,
    displayName?: string,
    topic?: string,
    avatar?: Asset | null,
  ) => {
    if (!this.instance) throw new Error("Client not initialized");
    const room = this.instance.getRoom(roomId);

    if (!room) throw new Error("Room not found");

    if (displayName) await room.setName(displayName);

    if (topic) await room.setTopic(topic);

    if (avatar === null) {
      await room.removeAvatar();
    } else if (avatar?.base64) {
      const bytes = Buffer.from(avatar.base64, "base64");
      const mimeType = avatar.type ?? "image/jpeg";

      await room.uploadAvatar(mimeType, bytes.buffer, {
        height: BigInt(32),
        width: BigInt(32),
        mimetype: mimeType,
        size: BigInt(avatar.fileSize ?? 0),
        thumbnailInfo: {
          height: BigInt(32),
          width: BigInt(32),
          mimetype: mimeType,
          size: BigInt(avatar.fileSize ?? 0),
        },
        thumbnailSource: undefined,
        blurhash: "",
        isAnimated: false,
      });
    }
  };

  public static leaveRoom = async (roomId: string) => {
    if (!this.instance) throw new Error("Client not initialized");
    const room = this.instance.getRoom(roomId);
    if (!room) throw new Error("Room not found");
    await room.leave();
    const updatedRoom = this.instance.getRoom(roomId);
    if (!updatedRoom) throw new Error("Room not found");
    await updatedRoom.forget();
    // Manually refresh the room list to update UI immediately
    await this.refreshRoomList();
  };

  //VERIFICATION AND ENCRYPTION METHODS

  /** Get the current device verification state */
  public static getVerificationState = () => {
    if (!this.instance) throw new Error("Client not initialized");
    return this.instance.encryption().verificationState();
  };

  /** Check if the current device is verified */
  public static isDeviceVerified = () => {
    if (!this.instance) return false;
    const state = this.instance.encryption().verificationState();
    return state === VerificationState.Verified;
  };

  /** Get the device ID of the current session */
  public static getDeviceId = () => {
    if (!this.instance) return null;
    const session = this.instance.session();
    return session?.deviceId || null;
  };

  /** Get verification details about the current user */
  public static getVerificationDetails = async () => {
    if (!this.instance) throw new Error("Client not initialized");
    const userId = this.instance.userId();
    if (!userId) throw new Error("User ID not found");

    const encryption = this.instance.encryption();
    const userIdentity = await encryption.userIdentity(userId, true);

    return {
      verificationState: encryption.verificationState(),
      isVerified: this.isDeviceVerified(),
      deviceId: this.getDeviceId(),
      userIdentity: userIdentity
        ? {
            isVerified: userIdentity.isVerified(),
            hasVerificationViolation: userIdentity.hasVerificationViolation(),
            masterKey: userIdentity.masterKey(),
          }
        : null,
    };
  };

  /** Enable backups for cross-signing (helps with device verification) */
  public static enableBackups = async () => {
    if (!this.instance) throw new Error("Client not initialized");
    const encryption = this.instance.encryption();
    await encryption.enableBackups();
  };

  /** Check if a backup exists on the server */
  public static backupExists = async () => {
    if (!this.instance) throw new Error("Client not initialized");
    return await this.instance.encryption().backupExistsOnServer();
  };

  /** Set up verification listeners - call this after login to enable verification */
  public static setupVerification = async (
    onRequest: VerificationRequestCallback,
    onEmojis: VerificationEmojisCallback,
    onStateChange: VerificationStateChangeCallback,
  ) => {
    if (!this.instance) throw new Error("Client not initialized");

    // Store callbacks
    this.onVerificationRequest = onRequest;
    this.onVerificationEmojis = onEmojis;
    this.onVerificationStateChange = onStateChange;

    // Get verification controller
    this.verificationController =
      await this.instance.getSessionVerificationController();

    // Create delegate to handle verification events
    const delegate: SessionVerificationControllerDelegate = {
      didReceiveVerificationRequest: (
        details: SessionVerificationRequestDetails,
      ) => {
        console.log("📩 Verification request received:", details);
        this.onVerificationStateChange?.("request");
        this.onVerificationRequest?.(details);
      },

      didAcceptVerificationRequest: () => {
        console.log("✅ Verification request accepted");
        this.onVerificationStateChange?.("accepted");
      },

      didStartSasVerification: () => {
        console.log("🔐 SAS verification started");
      },

      didReceiveVerificationData: (data: SessionVerificationData) => {
        console.log("📊 Verification data received:", data);

        if (data.tag === SessionVerificationData_Tags.Emojis) {
          const emojis = data.inner.emojis.map((emoji) => ({
            symbol: emoji.symbol(),
            description: emoji.description(),
          }));
          console.log("🎭 Emojis:", emojis);
          this.onVerificationStateChange?.("emojis");
          this.onVerificationEmojis?.(emojis);
        } else if (data.tag === SessionVerificationData_Tags.Decimals) {
          console.log("🔢 Decimals:", data.inner.values);
        }
      },

      didFail: () => {
        console.log("❌ Verification failed");
        this.onVerificationStateChange?.("failed");
      },

      didCancel: () => {
        console.log("🚫 Verification cancelled");
        this.onVerificationStateChange?.("cancelled");
      },

      didFinish: () => {
        console.log("🎉 Verification finished successfully!");
        this.onVerificationStateChange?.("success");
      },
    };

    // Set the delegate
    this.verificationController.setDelegate(delegate);
    console.log("✅ Verification controller set up successfully");
  };

  /** Acknowledge a verification request (call this when user taps on the verification notification) */
  public static acknowledgeVerification = async (
    senderId: string,
    flowId: string,
  ) => {
    if (!this.verificationController) {
      throw new Error("Verification controller not initialized");
    }
    await this.verificationController.acknowledgeVerificationRequest(
      senderId,
      flowId,
    );
    console.log("✅ Verification request acknowledged");
  };

  /** Accept the verification request and start SAS verification */
  public static acceptVerification = async () => {
    if (!this.verificationController) {
      throw new Error("Verification controller not initialized");
    }
    await this.verificationController.acceptVerificationRequest();
    await this.verificationController.startSasVerification();
    console.log("✅ Verification accepted and SAS started");
  };

  /** Accept the verification request without starting SAS */
  public static acceptVerificationRequest = async () => {
    if (!this.verificationController)
      throw new Error("Verification controller not initialized");
    await this.verificationController.acceptVerificationRequest();
    console.log("✅ Verification request accepted");
  };

  /** Approve the verification after comparing emojis */
  public static approveVerification = async () => {
    if (!this.verificationController) {
      throw new Error("Verification controller not initialized");
    }
    await this.verificationController.approveVerification();
    console.log("✅ Verification approved");
  };

  /** Decline the verification if emojis don't match */
  public static declineVerification = async () => {
    if (!this.verificationController)
      throw new Error("Verification controller not initialized");
    await this.verificationController.declineVerification();
    console.log("❌ Verification declined");
  };

  /** Cancel the verification flow */
  public static cancelVerification = async () => {
    if (!this.verificationController)
      throw new Error("Verification controller not initialized");
    await this.verificationController.cancelVerification();
    console.log("🚫 Verification cancelled");
  };

  /** Start the verification flow */
  public static startVerification = async () => {
    if (!this.instance) throw new Error("Client not initialized");
    if (!this.verificationController) {
      throw new Error("Verification controller not initialized");
    }
    await this.verificationController.startSasVerification();
    console.log("✅ Verification started");
  };

  /** Verify other user */
  public static verifyOtherUser = async (userId: string) => {
    if (!this.instance) throw new Error("Client not initialized");
    if (!this.verificationController) {
      throw new Error("Verification controller not initialized");
    }
    await this.verificationController.requestUserVerification(userId);
    console.log("✅ Verification requested");
  };

  /** Check if another user is verified by you */
  public static isUserVerified = async (userId: string) => {
    if (!this.instance) throw new Error("Client not initialized");
    try {
      const encryption = this.instance.encryption();
      const userIdentity = await encryption.userIdentity(userId, true);

      return !!userIdentity?.isVerified();
    } catch (error) {
      console.error("Failed to check user verification status:", error);
      return false;
    }
  };

  /** Get the current recovery state */
  public static getRecoveryState = () => {
    if (!this.instance) throw new Error("Client not initialized");
    return this.instance.encryption().recoveryState();
  };

  /** Check if recovery is enabled */
  public static isRecoveryEnabled = () => {
    if (!this.instance) return false;
    const state = this.instance.encryption().recoveryState();

    return state === RecoveryState.Enabled;
  };

  /** Enable recovery and get the recovery key
   * This will create a backup and return the recovery key that you MUST save */
  public static enableRecovery = async (passphrase?: string) => {
    if (!this.instance) throw new Error("Client not initialized");

    const encryption = this.instance.encryption();

    // Create a progress listener
    const progressListener: EnableRecoveryProgressListener = {
      onUpdate: (status) => {
        console.log("🔐 Recovery progress:", status);
      },
    };

    // Enable recovery and get the key
    const recoveryKey = await encryption.enableRecovery(
      true, // waitForBackupsToUpload
      passphrase,
      progressListener,
    );

    console.log("✅ Recovery enabled! Save your recovery key securely.");
    return recoveryKey;
  };

  /** Reset the recovery key and get a new one
   * Use this if you lost your old recovery key*/
  public static resetRecoveryKey = async () => {
    if (!this.instance) throw new Error("Client not initialized");

    const encryption = this.instance.encryption();
    const newRecoveryKey = await encryption.resetRecoveryKey();

    console.log("✅ Recovery key reset! Save your new recovery key securely.");
    return newRecoveryKey;
  };

  /** Recover using a recovery key
   * Use this to restore access to encrypted message */
  public static recoverWithKey = async (recoveryKey: string) => {
    if (!this.instance) throw new Error("Client not initialized");

    const encryption = this.instance.encryption();
    await encryption.recover(recoveryKey);

    console.log("✅ Successfully recovered using recovery key!");
  };

  /** Disable recovery (removes backup and recovery key)
   * Warning: This will prevent you from recovering encrypted messages */
  public static disableRecovery = async () => {
    if (!this.instance) throw new Error("Client not initialized");

    const encryption = this.instance.encryption();
    await encryption.disableRecovery();

    console.log("⚠️ Recovery disabled");
  };

  public static resetIdentity = async () => {
    if (!this.instance) throw new Error("Client not initialized");
    await this.instance.encryption().resetIdentity();
    console.log("✅ Identity reset successfully");
  };

  // PUSH NOTIFICATIONS METHODS

  /** Get all pushers registered for this user */
  public static getPushers = async () => {
    if (!this.instance) throw new Error("Client not initialized");

    const session = this.instance.session();
    if (!session) throw new Error("No active session");

    try {
      const response = await fetch(
        `${session.homeserverUrl}${MATRIX_ENDPOINTS.PUSHERS_GET}`,
        {
          method: "GET",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${session.accessToken}`,
          },
        },
      );

      if (!response.ok) {
        const errorText = await response.text();
        throw new Error(
          `Failed to get pushers: ${response.status} - ${errorText}`,
        );
      }

      const data = await response.json();
      return data.pushers || [];
    } catch (error) {
      console.error("Failed to get pushers:", error);
      throw error;
    }
  };

  /** Check if a pusher is already registered for this device */
  public static isPusherRegistered = async (pushToken: string) => {
    try {
      const pushers = await this.getPushers();
      if (!this.instance) throw new Error("Client not initialized");
      const session = this.instance.session();
      if (!session) throw new Error("No active session");

      return pushers.some(
        (pusher: {
          pushkey: string;
          app_id: string;
          device_display_name: string;
        }) =>
          pusher.pushkey === pushToken &&
          pusher.app_id === APP_ID &&
          pusher.device_display_name === session.deviceId,
      );
    } catch (error) {
      console.error("Failed to check pusher registration:", error);
      return false;
    }
  };

  /** Register a pusher with the homeserver for push notifications */
  public static setPusher = async (pushToken: string) => {
    if (!this.instance) throw new Error("Client not initialized");

    const session = this.instance.session();
    if (!session) throw new Error("No active session");

    const pusherData = {
      pushkey: pushToken,
      kind: "http",
      app_id: APP_ID,
      app_display_name: "Cloak",
      device_display_name: session.deviceId || "Mobile Device",
      profile_tag: "", // Optional: for multiple pushers per device
      lang: "en",
      data: {
        url: `${SygnalURL}/${MATRIX_ENDPOINTS.PUSH_GATEWAY_URL}`,
      },
    };

    try {
      const response = await fetch(
        `${session.homeserverUrl}${MATRIX_ENDPOINTS.PUSHERS_SET}`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${session.accessToken}`,
          },
          body: JSON.stringify(pusherData),
        },
      );

      if (!response.ok) {
        console.log("Failed to set pusher:", response);
        const errorText = await response.text();
        throw new Error(
          `Failed to set pusher: ${response.status} - ${errorText}`,
        );
      }

      return true;
    } catch (error) {
      console.error("Failed to register pusher:", error);
      throw error;
    }
  };

  /** Remove a pusher from the homeserver */
  public static removePusher = async (pushToken: string) => {
    if (!this.instance) throw new Error("Client not initialized");

    const session = this.instance.session();
    if (!session) throw new Error("No active session");

    const pusherData = {
      pushkey: pushToken,
      kind: null, // Setting kind to null removes the pusher
      app_id: APP_ID,
    };

    try {
      const response = await fetch(
        `${session.homeserverUrl}${MATRIX_ENDPOINTS.PUSHERS_SET}`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${session.accessToken}`,
          },
          body: JSON.stringify(pusherData),
        },
      );

      if (!response.ok) {
        const errorText = await response.text();
        throw new Error(
          `Failed to remove pusher: ${response.status} - ${errorText}`,
        );
      }

      console.log("Pusher removed successfully from homeserver");
      return true;
    } catch (error) {
      console.error("Failed to remove pusher:", error);
      throw error;
    }
  };
}

