import { Block, Text } from "@prototyp/skeletor";
import type { NativeStackScreenProps } from "@react-navigation/native-stack";
import { useAtom } from "jotai";
import { MatrixAtoms } from "modules/matrix-client/jotai";
import { MatrixService } from "modules/matrix-client/services";
import { type FC, useEffect, useState } from "react";
import { Alert, Image, StyleSheet } from "react-native";
import { Button, ScreenLayout } from "shared/components";
import { Colors, TextSize } from "shared/styles";

export const VerifyUser: FC<NativeStackScreenProps<Routes, "verifyUser">> = ({
  route,
  navigation,
}) => {
  const { userId } = route.params;
  const [loading, setLoading] = useState(false);
  const [verificationStatus, setVerificationStatus] = useAtom(
    MatrixAtoms.verificationStatus,
  );
  const isWaiting = verificationStatus === "waiting" || loading;
  const isCancelled = verificationStatus === "cancelled";
  const isAccepted = verificationStatus === "accepted";

  const handleStartVerification = async () => {
    try {
      setLoading(true);
      setVerificationStatus("waiting");
      await MatrixService.verifyOtherUser(userId);
    } catch (error) {
      console.error(error);
      setVerificationStatus("idle");
      Alert.alert("Error", "Failed to start verification");
    } finally {
      setLoading(false);
    }
  };

  const handleStartEmojiVerification = async () => {
    try {
      setLoading(true);
      setVerificationStatus("waiting");
      await MatrixService.startVerification();
    } catch (error) {
      console.error(error);
      setVerificationStatus("accepted");
      Alert.alert("Error", "Failed to start emoji verification");
    } finally {
      setLoading(false);
    }
  };

  const handleGoBack = async () => {
    try {
      if (verificationStatus !== "idle") {
        await MatrixService.cancelVerification();
        setVerificationStatus("cancelled");
        return;
      }
      navigation.goBack();
    } catch (error) {
      console.error(error);
      navigation.goBack();
    }
  };

  useEffect(() => {
    if (
      verificationStatus === "success" ||
      verificationStatus === "failed" ||
      verificationStatus === "cancelled"
    ) {
      // Reset verification status when verification is complete or failed
      setVerificationStatus("idle");
      navigation.goBack();
    }
  }, [verificationStatus]);

  return (
    <ScreenLayout type="modal">
      <Block flex={1} justify="space-between" align="center">
        <Block align="center" justify="center">
          <Block align="center" justify="center">
            <>
              <Image
                source={
                  isWaiting
                    ? require("assets/images/hourglass.png")
                    : require("assets/images/lock.png")
                }
                width={108}
                height={120}
              />
              <Text
                size={TextSize.large}
                margins={{ marginTop: 40, marginBottom: 8 }}
              >
                {isWaiting
                  ? "Waiting for the other user"
                  : isAccepted
                    ? "Ready to start emoji verification"
                    : isCancelled
                      ? "Verification canceled"
                      : "Verify this user?"}
              </Text>
              <Text color={Colors.white80} textAlign="center">
                {isWaiting
                  ? "Once accepted you'll be able to continue with the verification."
                  : isAccepted
                    ? "The other device accepted the request. Start the emoji verification."
                    : isCancelled
                      ? "The other device canceled the verification. You can try again."
                      : "For extra security, verify this user by comparing a set of emojis on your devices. Do this by using a trusted way to communicate."}
              </Text>
            </>
          </Block>
        </Block>

        <Block paddings={[40, 0]} flexDirection="row" gap={12} width="100%">
          <Block flex={1}>
            <Button.Ghost onPress={handleGoBack}>Cancel</Button.Ghost>
          </Block>
          <Block flex={1}>
            {!isWaiting && (
              <Button.Primary
                width="100%"
                disabled={isWaiting}
                style={styles.next}
                onPress={
                  isAccepted
                    ? handleStartEmojiVerification
                    : handleStartVerification
                }
              >
                {isAccepted ? "Start emoji verification" : "Start verification"}
              </Button.Primary>
            )}
          </Block>
        </Block>
      </Block>
    </ScreenLayout>
  );
};

const styles = StyleSheet.create({
  next: {
    width: "100%",
  },
  button: {
    width: "100%",
  },
});

