import { Block, Text } from "@prototyp/skeletor";
import type { NativeStackScreenProps } from "@react-navigation/native-stack";
import { useAtomValue } from "jotai";
import { MatrixAtoms } from "modules/matrix-client/jotai";
import { MatrixService } from "modules/matrix-client/services";
import { type FC, useEffect, useState } from "react";
import { ActivityIndicator, Image } from "react-native";
import Toast from "react-native-toast-message";
import { Button, GoBackHeader, ScreenLayout } from "shared/components";
import { Colors, TextSize } from "shared/styles";

export const VerifyWithDevice: FC<
  NativeStackScreenProps<Routes, "verifyWithDevice">
> = ({ navigation }) => {
  const client = useAtomValue(MatrixAtoms.matrixClient);
  const [isWaiting, setIsWaiting] = useState(true);
  const [deviceId, setDeviceId] = useState<string | null>(null);

  useEffect(() => {
    // Get the device ID to show the user
    const id = MatrixService.getDeviceId();
    setDeviceId(id);

    // Check verification status periodically
    const checkInterval = setInterval(async () => {
      const isVerified = MatrixService.isDeviceVerified();
      if (isVerified) {
        clearInterval(checkInterval);
        Toast.show({
          text1: "Device verified successfully! 🎉",
          text2: "You can now access your encrypted messages",
          type: "success",
        });
        navigation.reset({
          index: 0,
          routes: [{ name: "home" }],
        });
      }
    }, 2000);

    return () => clearInterval(checkInterval);
  }, [navigation]);

  const handleSkip = () => {
    navigation.goBack();
  };

  return (
    <ScreenLayout>
      <GoBackHeader />
      <Block flex={1} justify="space-between">
        <Block flex={1} justify="center" align="center" gap={32}>
          <Block gap={12}>
            <Text
              size={TextSize.large}
              textAlign="center"
              font="InstrumentSans-Medium"
            >
              Verify with another device
            </Text>
            <Text
              textAlign="center"
              font="InstrumentSans-Regular"
              color={Colors.white50}
            >
              To verify this device and access your encrypted messages, follow
              these steps on a device that's already verified:
            </Text>
          </Block>

          <Block
            border={{ borderRadius: 12 }}
            background={Colors.white5}
            paddings={[20, 20]}
            gap={16}
            width="100%"
          >
            <Block flexDirection="row" gap={12}>
              <Text color={Colors.primary} font="InstrumentSans-Bold">
                1.
              </Text>
              <Text color={Colors.white80}>
                Open Element or this app on your other device
              </Text>
            </Block>
            <Block flexDirection="row" gap={12}>
              <Text color={Colors.primary} font="InstrumentSans-Bold">
                2.
              </Text>
              <Text color={Colors.white80}>
                Go to Settings → Security → Sessions
              </Text>
            </Block>
            <Block flexDirection="row" gap={12}>
              <Text color={Colors.primary} font="InstrumentSans-Bold">
                3.
              </Text>
              <Block flex={1}>
                <Text color={Colors.white80}>
                  Find this device and tap "Verify"
                </Text>
                {deviceId && (
                  <Text
                    color={Colors.white50}
                    size={TextSize.small}
                    margins={{ marginTop: 4 }}
                  >
                    Device ID: {deviceId}
                  </Text>
                )}
              </Block>
            </Block>
            <Block flexDirection="row" gap={12}>
              <Text color={Colors.primary} font="InstrumentSans-Bold">
                4.
              </Text>
              <Text color={Colors.white80}>
                Compare the emoji sequences and confirm if they match
              </Text>
            </Block>
          </Block>

          {isWaiting && (
            <Block flexDirection="row" align="center" gap={12}>
              <ActivityIndicator color={Colors.primary} />
              <Text color={Colors.white50}>
                Waiting for verification request...
              </Text>
            </Block>
          )}

          <Block
            border={{ borderRadius: 12 }}
            background={Colors.primary + "20"}
            paddings={[12, 16]}
            flexDirection="row"
            align="center"
            gap={12}
          >
            <Image
              source={require("assets/icons/info.png")}
              tintColor={Colors.primary}
              width={20}
              height={20}
            />
            <Text color={Colors.white80} size={TextSize.small} flex={1}>
              Don't have access to another verified device? Use your recovery
              key instead.
            </Text>
          </Block>
        </Block>

        <Button.Outline onPress={handleSkip}>Go Back</Button.Outline>
      </Block>
    </ScreenLayout>
  );
};

