import type { EventTimelineItem } from "@unomed/react-native-matrix-sdk";
import { TimelineItemContent_Tags } from "@unomed/react-native-matrix-sdk";

/** Filter out duplicate stateKeys for calls */
export const filterSameStateKey = (events: EventTimelineItem[]) => {
  const seenStateKeys = new Map<string, EventTimelineItem>();
  const filtered: EventTimelineItem[] = [];

  for (const event of events) {
    const stateKey =
      event.content.tag === TimelineItemContent_Tags.State &&
      event.content.inner.stateKey
        ? event.content.inner.stateKey
        : null;

    if (stateKey) {
      if (!seenStateKeys.has(stateKey)) {
        seenStateKeys.set(stateKey, event);
      }
    } else filtered.push(event);
  }

  const stateKeyEvents = Array.from(seenStateKeys.values());
  return [...filtered, ...stateKeyEvents].sort(
    (a, b) => Number(a.timestamp) - Number(b.timestamp),
  );
};

export const handleIsPreviousSameSender = (
  events: EventTimelineItem[],
  currentEvent: EventTimelineItem,
  index: number,
) => {
  const messageTypesEvents = events.filter((event) => {
    return event.content.tag === TimelineItemContent_Tags.MsgLike;
  });

  return messageTypesEvents[index - 1]?.sender === currentEvent?.sender;
};

