import { Block, Text } from "@prototyp/skeletor";
import type { NativeStackScreenProps } from "@react-navigation/native-stack";
import type { FC } from "react";
import { Image } from "react-native";
import { Button, ScreenLayout } from "shared/components";
import { Colors, TextSize } from "shared/styles";

export const ConfirmIdentity: FC<
  NativeStackScreenProps<Routes, "confirmIdentity">
> = ({ navigation }) => {
  return (
    <ScreenLayout>
      <Block flex={1}>
        <Block flex={1} justify="center" align="center" gap={24}>
          <Block gap={12}>
            <Text
              size={TextSize.large}
              textAlign="center"
              font="InstrumentSans-Medium"
            >
              Verify your device
            </Text>
            <Text
              textAlign="center"
              font="InstrumentSans-Regular"
              color={Colors.white50}
            >
              Verify this device to access your encrypted message history and
              set up secure messaging.
            </Text>
          </Block>

          <Block
            border={{ borderRadius: 12 }}
            background={Colors.white5}
            paddings={[16, 16]}
            gap={12}
          >
            <Block flexDirection="row" align="center" gap={12}>
              <Image
                source={require("assets/icons/info.png")}
                tintColor={Colors.primary}
                width={20}
                height={20}
              />
              <Text color={Colors.white80} size={TextSize.small}>
                Without verification, you won't be able to access messages sent
                before this login.
              </Text>
            </Block>
          </Block>
        </Block>
        <Block gap={12}>
          <Button.Primary
            onPress={() => navigation.navigate("verifyWithDevice")}
          >
            Verify with Another Device
          </Button.Primary>
          <Button.Outline
            onPress={() => navigation.navigate("enterRecoveryKey")}
          >
            Use Recovery Key
          </Button.Outline>
          <Button.Outline onPress={() => navigation.navigate("cantConfirm")}>
            Can't confirm identity?
          </Button.Outline>
        </Block>
      </Block>
    </ScreenLayout>
  );
};

