import { Block, Text } from "@prototyp/skeletor";
import type { NativeStackScreenProps } from "@react-navigation/native-stack";
import { MatrixService } from "modules/matrix-client/services";
import { type FC, useState } from "react";
import { KeyboardAvoidingView, Platform } from "react-native";
import Toast from "react-native-toast-message";
import {
  Button,
  GoBackHeader,
  Input,
  Loading,
  ScreenLayout,
} from "shared/components";
import { Colors, TextSize } from "shared/styles";

export const EnterRecoveryKey: FC<
  NativeStackScreenProps<Routes, "enterRecoveryKey">
> = ({ navigation }) => {
  const [recoveryKey, setRecoveryKey] = useState("");
  const [isLoading, setIsLoading] = useState(false);

  const handleContinue = async () => {
    if (!recoveryKey.trim()) return;

    try {
      setIsLoading(true);
      // The recover() method both restores encrypted messages AND verifies the device
      await MatrixService.recoverWithKey(recoveryKey);
      Toast.show({
        text1: "Device verified successfully! 🎉",
        text2: "You can now access your encrypted messages",
        type: "success",
      });
      navigation.reset({
        index: 0,
        routes: [{ name: "home" }],
      });
    } catch (error) {
      console.error(error);
      Toast.show({
        text1: "Invalid recovery key",
        text2: "Please check your recovery key and try again",
        type: "error",
      });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <ScreenLayout>
      {isLoading && <Loading text="Verifying with recovery key..." />}
      <GoBackHeader />
      <KeyboardAvoidingView
        style={{ flex: 1 }}
        behavior={Platform.OS === "ios" ? "padding" : "height"}
      >
        <Block flex={1} justify="space-between">
          <Block flex={1} justify="center" align="center" gap={32}>
            <Block gap={8}>
              <Text
                size={TextSize.large}
                textAlign="center"
                font="InstrumentSans-Medium"
              >
                Enter your recovery key
              </Text>
              <Text
                textAlign="center"
                font="InstrumentSans-Regular"
                color={Colors.white50}
              >
                This will verify your device and restore access to your
                encrypted message history. Make sure nobody can see this
                screen.
              </Text>
            </Block>

            <Block width="100%">
              <Input
                placeholder="Recovery key"
                value={recoveryKey}
                onChangeText={setRecoveryKey}
                autoCapitalize="none"
                autoCorrect={false}
                secureTextEntry
              />
            </Block>
          </Block>

          <Block width="100%" paddings={[0, 52]} margins={{ marginBottom: 20 }}>
            <Button.Primary
              size="medium"
              width="100%"
              onPress={handleContinue}
              disabled={!recoveryKey.trim()}
            >
              Continue
            </Button.Primary>
          </Block>
        </Block>
      </KeyboardAvoidingView>
    </ScreenLayout>
  );
};

